<script>
import {Bar} from 'vue-chartjs'

export default {
    extends: Bar,
    data() {
        return {
            url: '/web/payments',
            backgroundColor: ['green', 'purple', 'blue', 'orange', 'beige', 'grey', 'yellow', 'brown', 'pink', 'red', 'black'],
            data: [],
            labels: [],
        }
    },

    mounted() {
        this.getReportInvoicePayments();
    },

    methods: {
        getReportInvoicePayments: function () {
            axios.get(this.url)
                .then((response) => {
                    console.log(response.data.paymentTypes.length);
                    this.labels = response.data.paymentTypes.length !== 0 ? response.data.paymentTypes : ['Cash'];
                    this.data = response.data.payments.length !== 0 ? response.data.payments : [0];
                    if (this.data) {
                        this.renderChart({
                            labels: this.labels,
                            datasets: [
                                {
                                    label: 'Total',
                                    backgroundColor: this.backgroundColor,
                                    data: this.data
                                }
                            ]
                        }, {
                            responsive: true,
                            maintainAspectRatio: false,
                            legend: {
                                display: false
                            },
                            scales: {
                                yAxes: [{
                                    ticks: {
                                        beginAtZero: true,
                                        stepSize: 100,
                                    }
                                }]
                            }
                        })
                    }
                })
                .catch((error) => {
                    console.log(error);
                    this.$notify({
                        type: 'error',
                        title: 'Error',
                        text: 'Could not load invoice payments report.',
                        duration: 6000,
                    });
                });
        },

    },
}
</script>
